const passScore = Number($('Normalize Candidate').first().json.passScore) || 4;

return $input.all().map(item => {
  const raw = String(item.json.text || '');
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  const clean = start >= 0 && end > start ? raw.slice(start, end + 1) : raw;
  let parsed;
  try {
    parsed = JSON.parse(clean);
  } catch (e) {
    throw new Error('AI output is not valid JSON: ' + raw.slice(0, 200));
  }
  const score = Number(parsed.score);
  if (!Number.isInteger(score) || score < 1 || score > 5) {
    throw new Error('AI score must be an integer 1-5, got: ' + parsed.score);
  }
  if (!Array.isArray(parsed.strengths) || !Array.isArray(parsed.concerns) || !parsed.summary) {
    throw new Error('AI output missing strengths, concerns or summary');
  }
  // Routing follows the score, so the AI cannot invite a low scorer or reject a high one
  const passed = score >= passScore;
  const aiStep = String(parsed.next_step || '').toLowerCase();
  const nextStep = passed ? 'interview' : (aiStep === 'reject' ? 'reject' : 'hold');
  return {
    json: {
      score,
      passed,
      nextStep,
      strengths: parsed.strengths.slice(0, 3).map(String),
      concerns: parsed.concerns.slice(0, 2).map(String),
      summary: String(parsed.summary)
    }
  };
});

